-- Posts module: built-in template library (pub_id NULL = shared across all publications).
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_1', NULL, 'Weekly roundup', 'post', 'Intro, top stories, quick hits, sponsor slot, referral block.', '{"blocks":[{"id":"b1736nu","type":"paragraph","data":{"html":"Hey {{subscriber.first_name|there}} 👋"}},{"id":"b2i9iue","type":"paragraph","data":{"html":"Here is what mattered this week, in five minutes or less."}},{"id":"b3mtex3","type":"toc","data":{}},{"id":"b4ki1y6","type":"heading","data":{"level":2,"html":"The big story"}},{"id":"b5khpuo","type":"paragraph","data":{"html":"Lead with the most important story of the week. What happened, why it matters, and what happens next."}},{"id":"b6yhsij","type":"ad","data":{"label":"Together with","headline":"Your sponsor headline goes here","body":"One or two sentences about the sponsor and why readers should care.","url":"https://example.com","cta":"Learn more"}},{"id":"b7dc9to","type":"heading","data":{"level":2,"html":"Three things worth your time"}},{"id":"b82tyrs","type":"list","data":{"ordered":true,"items":["<strong>First link</strong> — one sentence on why it is worth clicking.","<strong>Second link</strong> — the takeaway in a line.","<strong>Third link</strong> — a surprising detail."]}},{"id":"b9yfvip","type":"heading","data":{"level":2,"html":"Quick hits"}},{"id":"baps0q6","type":"list","data":{"ordered":false,"items":["Short update one","Short update two","Short update three"]}},{"id":"bbdrqfn","type":"divider","data":{"style":"dots"}},{"id":"bc2u7ty","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}},{"id":"bd9wy1l","type":"recommendations","data":{"title":"Newsletters we read","limit":3}},{"id":"be00apa","type":"paragraph","data":{"html":"See you next week,<br>{{publication.name}}"}}]}', '{"email":{"accent":"#f59e0b","link":"#b45309","button_bg":"#111827","font_size":17},"web":{"accent":"#f59e0b"}}', 0, 1792913220604, 1792913220604);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_2', NULL, 'Long-form essay', 'post', 'A focused essay with pull quote, footnotes and a clean serif style.', '{"blocks":[{"id":"bf8931j","type":"paragraph","data":{"html":"Open with a scene, a question, or a surprising fact that pulls the reader in."}},{"id":"bgdqm5v","type":"heading","data":{"level":2,"html":"The argument"}},{"id":"bh23jf3","type":"paragraph","data":{"html":"State your thesis clearly. Back it up with evidence<span data-footnote=\"Cite your sources here: https://example.com\"></span>."}},{"id":"biglasp","type":"quote","data":{"html":"A memorable line from the essay, set apart for emphasis.","cite":"","style":{"variant":"pull"}}},{"id":"bjr1vo3","type":"heading","data":{"level":2,"html":"The counterpoint"}},{"id":"bk03trc","type":"paragraph","data":{"html":"Steelman the opposing view, then explain why your position still holds."}},{"id":"blrz5k6","type":"heading","data":{"level":2,"html":"What this means for you"}},{"id":"bmcu3hz","type":"paragraph","data":{"html":"Close with the practical implication and a call to reflect or reply."}},{"id":"bn2i07h","type":"paywall","data":{}},{"id":"bojp3s9","type":"paragraph","data":{"html":"Premium readers get the extended analysis below the paywall break."}},{"id":"bpcqi5r","type":"divider","data":{"style":"line"}},{"id":"bqz3u58","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":18,"line_height":1.7,"accent":"#7c3aed","link":"#6d28d9"},"web":{"font":"Lora, Georgia, serif","heading_font":"Lora, Georgia, serif","accent":"#7c3aed"}}', 0, 1792913220604, 1792913220604);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_3', NULL, 'Curated links', 'post', 'A link digest with sections, short commentary and a sponsor.', '{"blocks":[{"id":"brr17j8","type":"paragraph","data":{"html":"The best things I found on the internet this week, hand-picked for {{subscriber.first_name|you}}."}},{"id":"bs8eksa","type":"heading","data":{"level":3,"html":"📚 Read"}},{"id":"btdffik","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">Article title</a> — why it is great.","<a href=\"https://example.com\">Article title</a> — the key insight."]}},{"id":"buhbmk7","type":"heading","data":{"level":3,"html":"🎧 Listen"}},{"id":"bvsu7wd","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">Podcast episode</a> — the best 10 minutes."]}},{"id":"bwceddn","type":"ad","data":{"label":"Together with","headline":"Your sponsor headline goes here","body":"One or two sentences about the sponsor and why readers should care.","url":"https://example.com","cta":"Learn more"}},{"id":"bxpgyhk","type":"heading","data":{"level":3,"html":"🛠 Use"}},{"id":"by83760","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">Tool name</a> — what it does in one line."]}},{"id":"bzy5ehc","type":"divider","data":{"style":"stars"}},{"id":"b102d71w","type":"recommendations","data":{"title":"Newsletters we read","limit":3}},{"id":"b118e662","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}}]}', '{"email":{"accent":"#10b981","link":"#047857"},"web":{"accent":"#10b981"}}', 0, 1792913220604, 1792913220604);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_4', NULL, 'Product update', 'post', 'Release notes with hero, feature columns and a CTA.', '{"blocks":[{"id":"b142mlm8","type":"section","data":{"blocks":[{"id":"b123hu56","type":"heading","data":{"level":2,"html":"What is new this month"}},{"id":"b13pe51q","type":"paragraph","data":{"html":"A one-line summary of the biggest improvement we shipped."}}],"style":{"bg":"#eff6ff","padding":20,"radius":10}}},{"id":"b1598bvy","type":"heading","data":{"level":3,"html":"Highlights"}},{"id":"b1aetcnp","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"b16q4eu0","type":"heading","data":{"level":4,"html":"Feature one"}},{"id":"b17py9vb","type":"paragraph","data":{"html":"What it does and who it helps."}}]},{"blocks":[{"id":"b18zvkix","type":"heading","data":{"level":4,"html":"Feature two"}},{"id":"b19vpkzt","type":"paragraph","data":{"html":"What it does and who it helps."}}]}]}},{"id":"b1bxsse3","type":"heading","data":{"level":3,"html":"Improvements"}},{"id":"b1cpp700","type":"list","data":{"ordered":false,"items":["Faster loading on large accounts","New keyboard shortcuts","Bug fixes and polish"]}},{"id":"b1duk9a0","type":"button","data":{"label":"Try it now","url":"https://example.com","align":"center"}},{"id":"b1e7sgyf","type":"divider","data":{"style":"line"}},{"id":"b1frf6t1","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}}]}', '{"email":{"accent":"#2563eb","link":"#1d4ed8","button_bg":"#2563eb","radius":10},"web":{"accent":"#2563eb"}}', 0, 1792913220604, 1792913220604);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_5', NULL, 'Interview', 'post', 'Q&A format with intro, quotes and key takeaways.', '{"blocks":[{"id":"b1govj62","type":"paragraph","data":{"html":"This week I sat down with <strong>Guest Name</strong>, who does something fascinating. Here is our conversation, lightly edited."}},{"id":"b1h7ujtg","type":"heading","data":{"level":3,"html":"Key takeaways"}},{"id":"b1iayiom","type":"list","data":{"ordered":false,"items":["Takeaway one","Takeaway two","Takeaway three"]}},{"id":"b1jqyml5","type":"divider","data":{"style":"line"}},{"id":"b1kkcyto","type":"paragraph","data":{"html":"<strong>Q: First question?</strong>"}},{"id":"b1lwtpeh","type":"paragraph","data":{"html":"Answer in the guest’s own words."}},{"id":"b1m7ht81","type":"quote","data":{"html":"The most quotable line from the interview.","cite":"Guest Name","style":{"variant":"box"}}},{"id":"b1n1oiyn","type":"paragraph","data":{"html":"<strong>Q: Second question?</strong>"}},{"id":"b1oyzik8","type":"paragraph","data":{"html":"Answer."}},{"id":"b1p7yaat","type":"ad","data":{"label":"Together with","headline":"Your sponsor headline goes here","body":"One or two sentences about the sponsor and why readers should care.","url":"https://example.com","cta":"Learn more"}},{"id":"b1qu5a80","type":"paragraph","data":{"html":"<strong>Q: What should readers do next?</strong>"}},{"id":"b1r01sbe","type":"paragraph","data":{"html":"Answer."}},{"id":"b1st8o3q","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}}]}', '{"email":{"accent":"#db2777","link":"#be185d"},"web":{"accent":"#db2777"}}', 0, 1792913220604, 1792913220604);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_6', NULL, 'Sponsored issue', 'post', 'Dedicated sponsor issue with primary and secondary placements.', '{"blocks":[{"id":"b1t068xr","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}}, today’s issue is brought to you by our partner. Thanks for supporting the companies that support this newsletter."}},{"id":"b1u90wqc","type":"ad","data":{"label":"Together with","headline":"Your sponsor headline goes here","body":"One or two sentences about the sponsor and why readers should care.","url":"https://example.com","cta":"Learn more"}},{"id":"b1v2wg14","type":"heading","data":{"level":2,"html":"This week’s story"}},{"id":"b1wuwjtk","type":"paragraph","data":{"html":"Your regular editorial content goes here."}},{"id":"b1yyopig","type":"section","data":{"blocks":[{"id":"b1xr5bm6","type":"paragraph","data":{"html":"<strong>Secondary sponsor</strong> — a short classified-style placement with a link."}}],"style":{"bg":"#fff7ed","padding":20,"radius":10}}},{"id":"b1zmyeew","type":"heading","data":{"level":2,"html":"One more thing"}},{"id":"b206z637","type":"paragraph","data":{"html":"Close with a personal note."}},{"id":"b210osrk","type":"recommendations","data":{"title":"Newsletters we read","limit":3}},{"id":"b22nzlkh","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}}]}', '{"email":{"accent":"#f97316","link":"#c2410c","button_bg":"#f97316","button_text":"#111827"},"web":{"accent":"#f97316"}}', 0, 1792913220604, 1792913220604);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, created_at, updated_at) VALUES ('tpl_builtin_7', NULL, 'Welcome email', 'welcome', 'Greets new subscribers and sets expectations.', '{"blocks":[{"id":"b23qebsq","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}},"}},{"id":"b24kbx1y","type":"paragraph","data":{"html":"Welcome to <strong>{{publication.name}}</strong>! You will get a new issue every week."}},{"id":"b25kzdiw","type":"heading","data":{"level":3,"html":"Start here"}},{"id":"b26ys1dj","type":"list","data":{"ordered":false,"items":["<a href=\"{{publication.url}}\">Browse the archive</a>","Reply to this email and tell me what you want to read about"]}},{"id":"b274x80w","type":"referral","data":{"title":"Share {{publication.name}} and earn rewards"}},{"id":"b281f5ex","type":"paragraph","data":{"html":"Talk soon!"}}]}', '{"email":{"accent":"#f59e0b"}}', 0, 1792913220604, 1792913220604);
CREATE INDEX IF NOT EXISTS idx_post_versions_post ON post_versions(post_id, created_at);
CREATE INDEX IF NOT EXISTS idx_draft_comments_post ON draft_comments(post_id);
CREATE INDEX IF NOT EXISTS idx_sends_post ON sends(post_id);
CREATE INDEX IF NOT EXISTS idx_pv_ref ON page_views(ref_id);
